import {IERC20, IRewardRouterV2, IGlpManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        GlpManagerMock gm = new GlpManagerMock();
        c = new DnGmxBatchingManager();
        c.initialize(
            IERC20(address(1)),
            IERC20(address(2)),
            IRewardRouterV2(address(3)),
            IGlpManager(address(gm)),
            address(4),
            address(5)
        );
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}

